  { url: 'https://simonwillison.net/atom/everything/', source: 'Simon Willison', tier: 5, category: 'developer' }
];

// Output each feed as a separate item for the RSS Read node
return feeds.map(feed => ({ json: feed }));

// Normalize RSS items and attach source metadata
// Handles different RSS feed formats (RSS 2.0, Atom)

const items = $input.all();
const batchMeta = $('Batch Feeds').first().json;

const results = [];
const now = new Date();
const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

for (const item of items) {
  const data = item.json;

  // Skip items with no title (malformed entries)
  if (!data.title) continue;

  // Parse publication date
  let pubDate;
  try {
    pubDate = new Date(data.pubDate || data.isoDate || data.published || data.date || now);
  } catch {
    pubDate = now;
  }

  // Only include items from the last 24 hours
  // (prevents re-processing old items on first run — remove this filter for initial backfill)
  if (pubDate < oneDayAgo) continue;

  // Extract content snippet (first 500 chars)
  const rawContent = data.content || data['content:encoded'] || data.summary || data.description || '';
  const textContent = rawContent.replace(/<[^>]*>/g, '').substring(0, 500);

  results.push({
    json: {
      title: data.title,
      url: data.link || data.url || data.guid || '',
      content_snippet: textContent,
      pub_date: pubDate.toISOString(),
      source: batchMeta.source || 'Unknown',
      tier: batchMeta.tier || 0,
      category: batchMeta.category || 'uncategorized',
      feed_url: batchMeta.url || ''
    }
  });
}

// Return results or empty item to prevent workflow stop
if (results.length === 0) {
  return [{ json: { _empty: true, source: batchMeta.source, message: 'No new items in last 24h' } }];
}

return results;

// Deduplicate items by URL across all feeds
// Also removes empty marker items from feeds with no new content

const items = $input.all();
const seen = new Set();
const deduped = [];

for (const item of items) {
  // Skip empty markers
  if (item.json._empty) continue;

  const url = item.json.url;
  if (!url || seen.has(url)) continue;

  seen.add(url);
  deduped.push(item);
}

console.log(`Deduplication: ${items.length} items → ${deduped.length} unique`);

if (deduped.length === 0) {
  return [{ json: { _no_items: true, message: 'No new unique items found across all feeds' } }];
}

return deduped;

// Wait 1 second between batches to respect API rate limits
await new Promise(resolve => setTimeout(resolve, 1000));
return $input.all();

