// Parse Claude API response and merge with original item data

const items = $input.all();
const results = [];

for (const item of items) {
  const original = item.json;

  // Get the original RSS item data from the batch
  const batchItem = $('Rate Limit Pause').first().json;

  let score = 0;
  let reason = 'Parse error';
  let category = 'unknown';
  let newsletter_tier = 'unknown';
  let newsletter_angle = '';

  try {
    // Claude API response structure
    const content = original.content;
    if (content && content[0] && content[0].text) {
      const text = content[0].text.replace(/```json|```/g, '').trim();
      const parsed = JSON.parse(text);
      score = parsed.score || 0;
      reason = parsed.reason || '';
      category = parsed.category || 'unknown';
      newsletter_tier = parsed.newsletter_tier || 'unknown';
      newsletter_angle = parsed.newsletter_angle || '';
    }
  } catch (e) {
    console.log('Claude parse error:', e.message);
    // Keep defaults — item will be filtered out by low score
  }

  results.push({
    json: {
      ...batchItem,
      relevance_score: score,
      score_reason: reason,
      ai_category: category,
      newsletter_tier: newsletter_tier,
      newsletter_angle: newsletter_angle,
      scored_at: new Date().toISOString()
    }
  });
}

return results;

// Count results for the daily summary
const items = $input.all();
const highScore = items.filter(i => i.json.relevance_score >= 8).length;
const medScore = items.filter(i => i.json.relevance_score >= 7 && i.json.relevance_score < 8).length;

return [{
  json: {
    total_saved: items.length,
    high_relevance: highScore,
    medium_relevance: medScore,
    date: new Date().toISOString().split('T')[0],
    summary: `Daily scan complete: ${items.length} items saved (${highScore} high, ${medScore} medium relevance)`
  }
}];

